else
	CRT="$T_80S"
	CRT_REF='#reference "../../shaders/crt-retro.glslp"'
fi

# ==============================================
# Set important RetroArch Settings
# ==============================================
set_ra() {
	# --- set necessary RetroArch settings ---
	set_cfg() {
		local key="$1" val="$2" file="$3"
		if grep -q "^${key} =" "$file"; then
			sed -i "s/^${key} = .*/${key} = \"${val}\"/" "$file"
		else
			echo "${key} = \"${val}\"" >> "$file"
		fi
		sleep 0.1
	}

	CONFIGS=(
		/home/ark/.config/retroarch/retroarch.cfg
		/home/ark/.config/retroarch32/retroarch.cfg
	)

	declare -A SETTINGS=(
		[config_save_on_exit]="true"
		[aspect_ratio_index]="22"
		[video_frame_delay_auto]="true"
	)

	for cfg in "${CONFIGS[@]}"; do
		for key in "${!SETTINGS[@]}"; do
			set_cfg "$key" "${SETTINGS[$key]}" "$cfg"
		done
	done
}

# ==============================================
# Config File Creation
# ==============================================
append_16_9_settings() {
	if (( W * 9 == H * 16 || H * 9 == W * 16 )); then
		cat >> "$1" << EOF
video_crop_overscan = "false"
video_viewport_bias_x = "0.050000"
EOF
	fi
}

