# ============================================================
# Remove Shaders Menu
# ============================================================
remove_shaders_menu() {
    while true; do
        local CHOICE
        CHOICE=$(dialog --clear \
						--cancel-label "$T_BACK" \
						--backtitle "$T_BACKTITLE" \
						--title "$T_REMOVE_MENU" \
						--menu "$T_SELECT" \
						10 40 6 \
						"1" "$T_HHTITLE" \
						"2" "$T_CONTITLE" \
						"3" "$T_REMOVE_ALL" \
						2>&1 > "$CURR_TTY")

        [[ $? -ne 0 ]] && return

        case "$CHOICE" in
            1) handheld_remove_menu ;;
            2) console_remove_menu ;;
			3) remove_all ;;
        esac
    done
}

# ============================================================
# Apply Shaders Menu
# ============================================================
apply_shaders_menu() {
	while true; do
	
		if [[ -f "$MON_FLAG" ]]; then
			BEZEL="crt-monitor.cfg"
		else
			BEZEL="crt-retro.cfg"
		fi

        local CHOICE
        CHOICE=$(dialog --clear \
						--cancel-label "$T_BACK" \
						--backtitle "$T_BACKTITLE" \
						--title "$T_APPLY_MENU" \
						--menu "$T_SELECT" \
						10 40 6 \
						"1" "$T_HHTITLE" \
						"2" "$T_CONTITLE" \
						"3" "$T_APPLY_ALL" \
						2>&1 > "$CURR_TTY")

        [[ $? -ne 0 ]] && return

        case "$CHOICE" in
            1) handheld_apply_menu ;;
            2) console_apply_menu ;;
			3) apply_all ;;
        esac
    done
}

# ==============================================
# CRT Style Chooser
# ==============================================
crt_style() {
    while true; do
		
		[[ -f "$MON_FLAG" ]] && CRT="$T_90S" || CRT="$T_80S"
        
		local CHOICE
        CHOICE=$(dialog --clear \
						--colors \
						--cancel-label "$T_BACK" \
						--backtitle "$T_BACKTITLE" \
						--title "$T_CRT_STYLE" \
						--menu "$T_CRT_STYLE: \Z4$CRT\Zn\n$T_SELECT" \
						10 40 6 \
						"1" "$T_80S" \
						"2" "$T_90S" \
						2>&1 > "$CURR_TTY")

        [[ $? -ne 0 ]] && return

        case "$CHOICE" in
            1)	
				CRT="$T_80S"
				CRT_REF='#reference "../../shaders/crt-retro.glslp"'
				touch "$TV_FLAG"
				rm -f "$MON_FLAG"
				return
				;;
            2) 	
				CRT="$T_90S"
				CRT_REF='#reference "../../shaders/crt-monitor.glslp"'
				touch "$MON_FLAG"
				rm -f "$TV_FLAG"
				return
				;;
        esac
    done
}

# ============================================================
# Main Menu
# ============================================================
main_menu() {
    while true; do
        local CHOICE
        CHOICE=$(dialog --clear \
						--colors \
						--cancel-label "$T_EXIT" \
						--backtitle "$T_BACKTITLE" \
						--title "$T_MAINTITLE" \
						--menu "$T_CRT_STYLE: \Z4$CRT\Zn\n$T_SELECT" \
						11 40 6 \
						"1" "$T_APPLY_MENU" \
						"2" "$T_REMOVE_MENU" \
						"3" "$T_CRT_STYLE" \
						2>&1 > "$CURR_TTY")

        [[ $? -ne 0 ]] && exit_menu

        case "$CHOICE" in
            1) apply_shaders_menu ;;
            2) remove_shaders_menu ;;
			3) crt_style ;;
        esac
    done
}

# =======================================================
# Legacy File Cleanup
# =======================================================
delete_files() {
	rm -f $SHADERPATH/gb.glslp
	rm -f $SHADERPATH/gbc.glslp
	rm -f $SHADERPATH/gba.glslp
	rm -f $SHADERPATH/gamegear.glslp
	rm -f $SHADERPATH/lynx.glslp
	rm -f $SHADERPATH/ngp.glslp
	rm -f $SHADERPATH/ngpc.glslp
	rm -f $SHADERPATH/wsc.glslp
	rm -f $SHADERPATH/crt.glslp
}

# ==============================================
# Shader File Creation
# ==============================================
create_files() {

dialog --backtitle "$T_BACKTITLE" --title "$T_DEPEND" --infobox "\n $T_INSTALL" 7 40 > "$CURR_TTY"

[[ -f "$SHADERPATH/gb.glslp" ]] && delete_files

# --- Create GameBoy shader reference ---
	cat > $SHADERPATH/gb-grid.glslp << 'EOF'
shaders = "2"
feedback_pass = "0"
shader0 = "shaders_glsl/motionblur/shaders/motionblur-simple.glsl"
alias0 = ""
wrap_mode0 = "clamp_to_border"
mipmap_input0 = "false"
filter_linear0 = "false"
float_framebuffer0 = "false"
srgb_framebuffer0 = "false"
shader1 = "shaders_glsl/handheld/shaders/gb-palette/gb-palette.glsl"
alias1 = ""
wrap_mode1 = "clamp_to_border"
mipmap_input1 = "false"
filter_linear1 = "false"
float_framebuffer1 = "false"
srgb_framebuffer1 = "false"
scale_type_x1 = "source"
scale_x1 = "1.000000"
scale_type_y1 = "source"
scale_y1 = "1.000000"
textures = "COLOR_PALETTE"
COLOR_PALETTE = "shaders_glsl/handheld/shaders/gb-palette/resources/palette-dmg.png"
COLOR_PALETTE_mipmap = "false"
COLOR_PALETTE_wrap_mode = "clamp_to_border"
EOF

# --- Create GameBoy Advance shader reference --
	cat > $SHADERPATH/gba-grid.glslp << 'EOF'
shaders = "2"
feedback_pass = "0"
shader0 = "shaders_glsl/handheld/shaders/color/gba-color.glsl"
alias0 = ""
wrap_mode0 = "clamp_to_border"
mipmap_input0 = "false"
filter_linear0 = "false"
float_framebuffer0 = "false"
srgb_framebuffer0 = "false"
scale_type_x0 = "source"
scale_x0 = "1.000000"
scale_type_y0 = "source"
scale_y0 = "1.000000"
shader1 = "shaders_glsl/motionblur/shaders/motionblur-simple.glsl"
alias1 = ""
wrap_mode1 = "clamp_to_border"
mipmap_input1 = "false"
filter_linear1 = "false"
float_framebuffer1 = "false"
srgb_framebuffer1 = "false"

EOF

# --- Create GameBoy Color shader reference ---
	cat > $SHADERPATH/gbc-grid.glslp << 'EOF'
shaders = "2"
feedback_pass = "0"
shader0 = "shaders_glsl/handheld/shaders/color/gbc-gambatte-color.glsl"
alias0 = ""
wrap_mode0 = "clamp_to_border"
mipmap_input0 = "false"
filter_linear0 = "false"
float_framebuffer0 = "false"
srgb_framebuffer0 = "false"
scale_type_x0 = "source"
scale_x0 = "1.000000"
